/// <summary>
/// The <c>METSalesOrderGuideService</c> class is used as a data contract to pass list of <c>METSalesOrderGuideRequestContract</c>
/// </summary>
[DataContractAttribute]
class METSalesOrderGuideRequestCollectionContract
{
    private CustAccount custAccount;
    private List        itemList  = new List(Types::Class);
    private DataAreaId  dataAreaId;

}

Method.Source:
/// <summary>
/// parm method for customer account number
/// </summary>
/// <param name = "_custAccount">customer account number</param>
/// <returns>customer account number</returns>
[DataMemberAttribute('CustomerAccountNumber')]
public CustAccount parmCustAccount(CustAccount _custAccount = custAccount)
{
    custAccount = _custAccount;
    return custAccount;
}

    /// <summary>
    /// Gets or sets the list of <c>METUpdateSalesInvoiceIntegrationStatusContract</c>
    /// </summary>
    /// <param name = "_itemList">List of collection items</param>
    /// <returns>List of <c>METSalesOrderGuideRequestContract</c></returns>
    [
        DataMemberAttribute('ItemList'),
        SysOperationLabelAttribute(literalstr("ItemList")),
        AifCollectionTypeAttribute('_itemList', Types::Class, classStr(METSalesOrderGuideRequestContract)),
        AifCollectionTypeAttribute('return', Types::Class, classStr(METSalesOrderGuideRequestContract))
    ]
    public List parmItemList(List _itemList = itemList)
    {
        itemList = _itemList;

        return itemList;
    }

/// <summary>
/// Gets/sets the company ID
/// </summary>
/// <param name = "_dataAreaId">company ID</param>
/// <returns>returns the company ID</returns>
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
{
    dataAreaId = _dataAreaId;
    return dataAreaId;
}
